// Biidaasige Park source inventory (bead st-bmyv.1): js/biidaasige-park-data.js generated by
// tools/build-biidaasige-park-data.mjs from CHECKED-IN fixtures (tools/fixtures/biidaasige/*.json).
//
// These tests defend the honesty contract:
//  1. Every built position is a current OSM node/way with a real ref; official-only features are lat=null/lon=null.
//  2. Every placed lat/lon is a true point in the real park polygon (not just the bounding box).
//  3. The broad-query outsiders (Cherry Beach, Corktown, far washroom/trails) are absent or context, never in-park.
//  4. Fitness is official-LISTED-unplaced (the old not-listed claim is gone).
//  5. The Owl identity is resolved by the named OSM structure way/1418541992; the maker pin is documented, approximate,
//     and never placed by default or used as a body origin.
//  6. Orientation is the OSM footprint long axis (estimates), never a surveyed facing.
//  7. Runtime helpers project through C.worldFromLatLon (detail + Eglinton), exclude unverified by default, and
//     return null (not a fabricated point) when the frame is absent.
//  8. The generator reads checked-in fixtures (no /tmp), writes one data file, and is not stale.
//  9. No feature is claimed "all implemented": every unplaced category is recorded in coverage.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const ROOT = new URL('..', import.meta.url).pathname;
const read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8');

function city() {
  const ctx = { window: {}, console };
  vm.createContext(ctx);
  vm.runInContext(read('js/biidaasige-park-data.js'), ctx, { filename: 'biidaasige-park-data.js' });
  return ctx.window.CITY;
}

const PROJ = (() => {
  const ctx = { window: {} };
  vm.createContext(ctx);
  vm.runInContext(read('js/toronto-geodata.js'), ctx);
  return ctx.window.CITY.GEO.frame.projection;
})();
function worldFromLatLon(lat, lon) {
  const e = (lon - PROJ.lon0) * PROJ.kx, n = (lat - PROJ.lat0) * PROJ.ky;
  const c = Math.cos(PROJ.theta), s = Math.sin(PROJ.theta);
  return { x: e * c - n * s - PROJ.ox, z: -(e * s + n * c) - PROJ.oz };
}

const C = city();
const D = C.BIIDAASIGE_PARK;

function pip(lat, lon, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const yi = ring[i][0], xi = ring[i][1], yj = ring[j][0], xj = ring[j][1];
    if ((yi > lat) !== (yj > lat) && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}
function distToRing(lat, lon, ring) {
  const kx = 111320 * Math.cos((lat * Math.PI) / 180), ky = 110540;
  const px = lon * kx, py = lat * ky;
  let best = Infinity;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const x1 = ring[j][1] * kx, y1 = ring[j][0] * ky, x2 = ring[i][1] * kx, y2 = ring[i][0] * ky;
    const dx = x2 - x1, dy = y2 - y1;
    const t = dx === 0 && dy === 0 ? 0 : Math.max(0, Math.min(1, ((px - x1) * dx + (py - y1) * dy) / (dx * dx + dy * dy)));
    best = Math.min(best, Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy)));
  }
  return best;
}

test('the park is the current OSM polygon with real bounds', () => {
  assert.equal(D.version, 3);
  assert.ok(Array.isArray(D.park.polygon) && D.park.polygon.length > 50, 'raw park ring');
  assert.equal(D.park.osmRef, 'way/813717630');
  const b = D.park.boundingBox;
  assert.ok(b.minLat < 43.643 && b.maxLat > 43.649 && b.minLon < -79.354 && b.maxLon > -79.344);
});

test('every built position is an OSM node/way with a real ref and finite lat/lon', () => {
  assert.ok(D.features.length >= 120, `verified feature count (${D.features.length})`);
  for (const f of D.features.concat(D.contextFeatures)) {
    assert.match(f.ref, /^(node|way)\/\d+$/, `${f.id} has an OSM ref`);
    assert.ok(Number.isFinite(f.lat) && Number.isFinite(f.lon), `${f.id} finite lat/lon`);
    assert.ok(f.placement.startsWith('osm'), `${f.id} placement is osm*`);
    if (f.geometryType === 'point') assert.equal(f.ring, null, `${f.id} point ring null`);
    else if (f.geometryType === 'line') assert.ok(f.ring.length >= 2, `${f.id} line`);
    else {
      assert.ok(f.ring.length >= 3, `${f.id} poly ring`);
      const a = f.ring[0], z = f.ring[f.ring.length - 1];
      assert.ok(Math.abs(a[0] - z[0]) < 1e-9 && Math.abs(a[1] - z[1]) < 1e-9, `${f.id} closed`);
    }
  }
});

test('every in-park coordinate is truly inside the park polygon, not merely the bounding box', () => {
  const ring = D.park.polygon;
  let placed = 0;
  for (const f of D.features) {
    if (f.spatialStatus !== 'in-park') continue;
    placed++;
    assert.ok(pip(f.lat, f.lon, ring), `${f.id} inside the park polygon (${f.lat}, ${f.lon})`);
  }
  assert.ok(placed > 120, `many placed points checked (${placed})`);
  // walk-in-only fixtures from the broader extract must be inside too
  const benches = D.features.filter((f) => f.kind === 'bench');
  assert.ok(benches.length > 30, `benches re-filtered from the broad extract (${benches.length})`);
  for (const b of benches) assert.ok(pip(b.lat, b.lon, ring), `${b.id} bench inside`);
  // Canoe Cove is water just outside the land ring but adjacent
  const canoe = D.features.find((f) => f.id === 'canoe-cove');
  assert.equal(canoe.spatialStatus, 'adjacent');
  assert.ok(distToRing(canoe.lat, canoe.lon, ring) < 20, 'Canoe Cove adjacent');
});

test('broad-query outsiders are absent from the built set and the catalog', () => {
  const names = D.features.concat(D.unverifiedFeatures, D.contextFeatures).map((f) => f.name).join(' | ');
  for (const o of ['Sackville', 'Corktown', 'Cherry Beach', 'McCleary', 'Leslie Lookout', 'Tommy Thompson']) {
    assert.ok(!names.includes(o), `no unrelated "${o}" feature`);
  }
  // no built datapoint carries a "not-listed"/guessed area tier
  for (const f of D.features) assert.ok(['osm-node', 'osm-way', 'osm-area', 'osm-line'].includes(f.placement), `${f.id}: ${f.placement}`);
});

test('fitness is official-LISTED-unplaced (the old not-listed claim is gone)', () => {
  const fit = D.unverifiedFeatures.find((f) => f.id === 'outdoor-fitness');
  assert.ok(fit, 'fitness is in the catalog');
  assert.equal(fit.status, 'official-listed-unplaced');
  assert.equal(fit.lat, null);
  assert.equal(fit.lon, null);
  assert.match(fit.evidence, /available west of Cableway Canyon/i);
  const coverage = D.coverage.find((c) => c.requested === 'fitness');
  assert.equal(coverage.status, 'official-listed-unplaced');
  // nothing anywhere says "not-listed" for fitness
  const dump = JSON.stringify(D);
  assert.ok(!/not-listed/i.test(dump.replace(/official-listed-unplaced/g, '')), 'no stale not-listed claim');
});

test('the Owl is resolved by the named OSM structure; maker pin stays approximate and unplaced by default', () => {
  const conflict = D.sourceConflicts.find((c) => c.id === 'snowy-owl-identity');
  assert.ok(conflict, 'source conflict recorded');
  assert.equal(conflict.status, 'resolved-by-named-osm-structure');
  assert.equal(conflict.claims.length, 3, 'historical claims plus the resolving named structure');
  // historical claims are preserved, not deleted
  const pin = conflict.claims.find((c) => /maker/i.test(c.source));
  assert.ok(pin && Math.abs(pin.lat - 43.6462889) < 1e-6 && Math.abs(pin.lon - -79.3496804) < 1e-6, 'maker KML coordinates retained exactly');
  assert.ok(conflict.separationM > 100, `the pins do not coincide (${conflict.separationM} m)`);
  assert.ok(/way\/1418541992/.test(conflict.resolution), 'resolution cites the named OSM structure');
  assert.ok(/not the body/i.test(conflict.resolution), 'centroid is explicitly not the body origin');

  // the named theatre AREA is exact and its every vertex lies inside the unnamed west play area
  const area = D.features.find((f) => f.id === 'snowy-owl-playground');
  assert.match(area.name, /unnamed in OSM/i);
  assert.equal(area.ref, 'way/1418127159');
  const theatre = D.features.find((f) => f.id === 'snowy-owl-theatre');
  assert.ok(theatre, 'the named Snowy Owl Theatre is placed');
  assert.equal(theatre.ref, 'way/1418541992');
  assert.equal(theatre.geometryType, 'polygon');
  assert.equal(theatre.ring.length, 18, 'exact raw 18-vertex theatre area');
  for (const [lat, lon] of theatre.ring) assert.ok(pip(lat, lon, area.ring), 'theatre vertex inside the west play area');
  // the generic area was never moved: its raw centroid is unchanged from the pre-correction source
  assert.ok(Math.abs(area.lat - 43.6453865) < 1e-6 && Math.abs(area.lon - -79.350948) < 1e-6, 'generic area not moved');
  assert.equal(area.model, undefined, 'no Owl model attached to the unnamed area');

  // the maker pin is unverified and never projected by default
  const pinRec = D.unverifiedFeatures.find((f) => f.id === 'snowy-owl-maker-pin');
  assert.equal(pinRec.status, 'source-conflict');
  assert.equal(pinRec.lat, null);
  assert.equal(pinRec.lon, null);
});

test('new playground=* equipment matches the checked-in raw source exactly', () => {
  const raw = JSON.parse(read('tools/fixtures/biidaasige/osm-equipment.json'));
  const byRef = new Map(raw.elements.map((e) => [`${e.type}/${e.id}`, e]));
  const ids = ['snowy-owl-theatre', 'cableway-20', 'cableway-40', 'swing-hill-node',
    'sandpit-1552431731', 'sandpit-1552431732', 'unnamed-playground-structure'];
  for (const id of ids) {
    const f = D.features.find((x) => x.id === id);
    assert.ok(f, `${id} is placed`);
    const el = byRef.get(f.ref);
    assert.ok(el, `${id} traces to the raw extract (${f.ref})`);
    if (el.geometry) {
      // the built fixture rounds to 7 dp (its convention); the raw source has full precision
      const raw = el.geometry.map((p) => [p.lat, p.lon]);
      assert.equal(f.ring.length, raw.length, `${id} ring vertex count`);
      for (let i = 0; i < raw.length; i++) {
        assert.ok(Math.abs(f.ring[i][0] - raw[i][0]) < 1e-7 && Math.abs(f.ring[i][1] - raw[i][1]) < 1e-7, `${id} vertex ${i} matches raw geometry`);
      }
    } else {
      assert.equal(f.lat, el.lat);
      assert.equal(f.lon, el.lon);
    }
  }
  // Badlands is de-duplicated by ref, not inserted twice
  assert.equal(D.features.filter((f) => f.ref === 'way/1418541993').length, 1, 'Badlands appears once');
  // the two cableways are two-endpoint map lines, measured separately from the published City lengths
  const short = D.features.find((f) => f.id === 'cableway-20');
  const long = D.features.find((f) => f.id === 'cableway-40');
  assert.equal(short.geometryType, 'line');
  assert.equal(short.ring.length, 2);
  assert.equal(long.ring.length, 2);
  assert.ok(short.mapLineLengthM < long.mapLineLengthM, `short cableway measured shorter (${short.mapLineLengthM} < ${long.mapLineLengthM})`);
  for (const f of [short, long]) assert.ok(/published/.test(f.name) && Number.isFinite(f.mapLineLengthM), `${f.id} keeps published + measured separate`);
  // swing is a single node (partial source), the unnamed structure identity is unresolved
  assert.equal(D.features.find((f) => f.id === 'swing-hill-node').geometryType, 'point');
  assert.match(D.features.find((f) => f.id === 'unnamed-playground-structure').name, /unresolved/i);
  // sandpits stay generic: not assigned to the mock beaver dam
  const dam = D.unverifiedFeatures.find((f) => f.id === 'mock-beaver-dam');
  assert.equal(dam.status, 'official-listed-unplaced');
  for (const id of ['sandpit-1552431731', 'sandpit-1552431732']) {
    assert.match(D.features.find((f) => f.id === id).evidence, /NOT proven|not proven/i);
  }
});

test('orientation is the OSM footprint long axis, an estimate, never a surveyed facing', () => {
  for (const f of D.features) {
    if (f.geometryType === 'point') {
      assert.equal(f.orientationDeg, null, `${f.id} point orientation null`);
      continue;
    }
    assert.ok(Number.isFinite(f.orientationDeg) && f.orientationDeg >= 0 && f.orientationDeg < 180, `${f.id} bearing`);
    assert.ok(['osm-footprint-long-axis', 'osm-line-endpoints'].includes(f.orientationSource), `${f.id} ${f.orientationSource}`);
    assert.equal(f.orientationConfidence, 'estimated', `${f.id} estimate`);
  }
});

test('coverage lists every requested category; nothing is falsely "all implemented"', () => {
  const wanted = ['owl', 'raccoon', 'badlands', 'cableway', 'swings', 'drum', 'dogpark-east', 'dogpark-west', 'firehall',
    'atlas-crane', 'bbq', 'fountains', 'tables', 'benches', 'bins', 'washrooms', 'firepit', 'fitness', 'markers',
    'signage', 'plantings', 'trails', 'canoe-cove', 'paddling', 'promenade', 'art-trail', 'event-lawn', 'promontory',
    'habitat', 'bridges', 'landings', 'steps', 'future', 'sandpits', 'unnamed-structure'];
  const have = new Set(D.coverage.map((c) => c.requested));
  for (const w of wanted) assert.ok(have.has(w), `coverage covers "${w}"`);
  // the Owl theatre area is now verified; the maker pin is not what verified it
  assert.equal(D.coverage.find((c) => c.requested === 'owl').status, 'verified-osm-structure');
  // cableway and swings are recorded as partial, not full
  assert.equal(D.coverage.find((c) => c.requested === 'cableway').status, 'verified-osm-partial');
  assert.equal(D.coverage.find((c) => c.requested === 'swings').status, 'verified-osm-partial');
  // the mock beaver dam stays unplaced and is never claimed from the sandpits
  assert.equal(D.coverage.find((c) => c.requested === 'mock-dam').status, 'unverified');
  // every non-verified coverage entry is a real gap we do not hide
  const gaps = D.coverage.filter((c) => !/^verified/.test(c.status));
  assert.ok(gaps.length >= 10, `honest gaps recorded (${gaps.length})`);
  // no current feature is future
  for (const f of D.features) assert.notEqual(f.phase, 'future', `${f.id} current`);
  assert.ok(D.unverifiedFeatures.some((f) => f.phase === 'future'), 'future work marked future');
});

test('runtime helpers project through C.worldFromLatLon (detail AND Eglinton), exclude unverified by default', () => {
  const C2 = city();
  const calls = interceptWorld(C2, 'detail');
  const pose = C2.biidaasigeParkPose('reaching-raccoon');
  assert.ok(pose && Number.isFinite(pose.x) && Number.isFinite(pose.z), 'raccoon projects');
  assert.ok(calls() > 0, 'the projection function was actually called');
  const ring = C2.biidaasigeParkRingWorld('badlands-scramble');
  assert.ok(ring.length >= 3 && ring.every((p) => Number.isFinite(p.x) && Number.isFinite(p.z)), 'ring projects');
  // unverified is excluded by default
  assert.equal(C2.biidaasigeParkWorld('outdoor-fitness'), null, 'unverified fitness not placed by default');
  assert.equal(C2.biidaasigeParkFeatures().length, D.features.length, 'default list is verified only');
  assert.equal(C2.biidaasigeParkFeatures({ includeUnverified: true }).length, D.features.length + D.unverifiedFeatures.length);
  // the Owl maker pin never becomes a world pose without explicit opt-in + document-only source
  assert.equal(C2.biidaasigeParkWorld('snowy-owl-maker-pin'), null, 'maker pin not placed by default');
  const optIn = C2.biidaasigeParkWorld('snowy-owl-maker-pin', { includeUnverified: true });
  assert.ok(optIn && optIn.placement === 'maker-pin', 'explicit opt-in returns the documented pin, labelled maker-pin');
  // Eglinton frame still projects the same WGS points through the same function
  const C3 = city();
  interceptWorld(C3, 'eglinton');
  assert.ok(C3.biidaasigeParkPose('atlas-crane'), 'projects in the Eglinton frame');
});

test('frame is guarded: without C.worldFromLatLon every projection returns null, never a made-up point', () => {
  const C4 = city();
  C4.worldFromLatLon = undefined;
  assert.equal(C4.biidaasigeParkProjectionAvailable(), false);
  assert.equal(C4.biidaasigeParkWorld('atlas-crane'), null);
  assert.equal(C4.biidaasigeParkRingWorld('badlands-scramble'), null);
  assert.equal(C4.biidaasigeParkPose('reaching-raccoon'), null);
  // identity/evidence survive even when a point cannot be projected
  assert.ok(C4.biidaasigeParkFeature('the-drum'));
  assert.equal(C4.biidaasigeParkCatalog().length, D.features.length + D.contextFeatures.length + D.unverifiedFeatures.length);
});

test('the generator uses checked-in fixtures (no /tmp) and writes only the one data file', () => {
  const builder = read('tools/build-biidaasige-park-data.mjs');
  assert.ok(!/\/tmp\//.test(builder), 'builder does not read /tmp');
  assert.ok(!/swarm/.test(builder), 'builder does not reference a private temp cache');
  assert.match(builder, /tools\/fixtures\/biidaasige/);
  for (const fx of ['osm-verified.json', 'osm-supplement.json', 'osm-equipment.json', 'official-catalog.json', 'coverage.json']) {
    assert.ok(fs.existsSync(path.join(ROOT, 'tools/fixtures/biidaasige', fx)), `fixture ${fx} is committed`);
  }
  const out = execFileSync(process.execPath, [path.join(ROOT, 'tools/build-biidaasige-park-data.mjs'), '--check'], { encoding: 'utf8' });
  assert.match(out, /up to date/);
  // the obsolete early generator/artifact are gone
  assert.ok(!fs.existsSync(path.join(ROOT, 'tools/build-biidaasige-inventory.mjs')), 'old generator removed');
  assert.ok(!fs.existsSync(path.join(ROOT, 'js/biidaasige-park-inventory.json')), 'old artifact removed');
});

function interceptWorld(Cc, frame) {
  let calls = 0;
  Cc.worldFromLatLon = (lat, lon) => {
    calls++;
    assert.ok(Number.isFinite(lat) && Number.isFinite(lon));
    const p = worldFromLatLon(lat, lon);
    return frame === 'eglinton' ? { x: p.x + 100000, z: p.z + 50000 } : p;
  };
  return () => calls;
}
